-- Allow authenticated members to download files only when the linked document is published.
-- The bucket remains private; signed URLs are short-lived and generated by the authenticated client.
create policy "Authenticated users download published legal files"
on storage.objects
for select
to authenticated
using (
  bucket_id = 'legal-documents'
  and exists (
    select 1
    from public.document_files df
    join public.documents d on d.id = df.document_id
    where df.storage_path = storage.objects.name
      and d.status = 'published'
  )
);
